const WORLD={
people:{title:'동네 사람들',sub:'인물 · 광희동 네트워크',intro:'가게 하나에 얽힌 사람들. 순애상회의 소식은 이들을 거쳐 동네 전체로 번진다.',cards:[
['01 · 옆집 사장','굴나라','40대 여성. 옆집 우즈벡 삼사, 화덕 고기빵 가게 사장. 타티야나의 언니 겸 앙숙이다. 손님 뺏기와 호객 경쟁으로 매일 투닥이지만, 저녁이면 서로 남은 음식을 바꿔 먹는다. 연애 훈수만큼은 언제나 1순위.','assets/npc-gulnara.webp'],
['02 · 난로 옆 지정석','고려인 어르신들','사진 왼쪽부터 김류바(79세 여성), 최니나(76세 여성), 한표도르(83세 남성). 고려말을 쓰는 할머니·할아버지 3인방이다. 타티야나를 “순애야”라 부르며 손주처럼 대한다. 시집 참견, 소문 확산, 화투 담당. 가게 구석 난로 옆이 지정석이다.','assets/npc-elders.webp'],
['03 · 외상 장부 단골','아이게림','20대 여성, 카자흐스탄 출신 대학원생. 외상 장부에 가장 자주 이름을 올린다. 타티야나에게 한국 행정서류를 부탁하고, 대신 가게의 SNS 홍보와 번역을 맡는다. 동네 사정을 빠르게 알아차리는 관찰자.','assets/npc-aigerim.webp'],
['04 · 부산발 방문객','원양선 선원들','사진 왼쪽부터 바실리(38세 남성·대머리·거구·갈색 수염), 코스챠(27세 남성·갈색 머리), 그리샤(41세 남성·회색 수염). 부산 감천항에 정박한 러시아 원양선 선원들이다. 보선장 아버지의 옛 부하들로, 상경하면 꼭 가게에 들러 보드카를 깐다. 딸의 소식을 아버지에게 실시간으로 보고하는 스파이이기도 하다.','assets/npc-sailors.webp'],
['05 · 블라디보스토크 연결','류드밀라 & 미하일','엄마 류드밀라는 매일 영상통화로 결혼, 밥, 옷차림을 챙긴다. 은퇴한 보선장 아빠 미하일은 말수 적은 딸바보. 애정 표현은 주로 매듭 강의로 돌아온다. 두 사람은 화면과 전화로만 등장한다.','assets/npc-parents.webp'],
['06 · 월세의 결정권자','오말순','70대 한국인 여성, 순애상회 건물주. 처음에는 외국인 세입자를 경계했지만, 타티야나가 이삿짐과 김장을 맨손으로 해치운 뒤 열렬한 팬이 됐다. 월세 협상에도 변수가 생겼다.','assets/npc-landlady.webp'],
['07 · 순찰 중입니다','김희민','26세 남성, 광희동 파출소 순경. 원칙대로 움직이는 FM이지만 겁이 많다. 동네 사고는 죄다 순애상회 쪽에서 터지는 것 같아 의심 반, 핑계 반으로 순찰을 온다. 그러고는 덤을 받아먹고 돌아간다. 타티야나를 짝사랑 중이다.','assets/npc-heemin.webp']]},
places:{title:'골목 안내서',sub:'로컬 · 한국 속 작은 유라시아',intro:'키릴 문자 간판 아래로 동네의 하루가 흐른다. 순애상회를 중심으로 이어지는 생활권.',cards:[
['01 · 거리','광희동 중앙아시아거리','동대문역사문화공원역 일대. 키릴 문자 간판, 몽골타워, 환전소와 국제택배, 우즈벡 식당과 러시아 식료품점이 밀집해 있다. 한국 속 작은 유라시아.'],
['02 · 문에 달린 종','순애상회 1층','좁고 긴 가게에 진열대, 냉동고, 계산대가 놓여 있다. 구석에는 난로와 사모바르, 계산대 뒤에는 외상 장부와 할머니 사진. 문이 열릴 때마다 종이 시끄럽게 울린다.'],
['03 · 가게 위의 생활','2층 살림집','원룸형 살림집. 카펫은 바닥뿐 아니라 벽에도 걸려 있고, 두꺼운 이불과 화분이 많다. 창가에서는 거리가 내려다보인다. 타티야나의 불만은 약한 욕실 수압.'],
['04 · 물류의 뒤편','뒤편 창고','물류박스, 포장끈과 로프가 쌓여 있다. 타티야나가 박스를 맨손으로 옮기는 곳. 문은 잘 안 닫히고 형광등은 깜빡인다. 사람 눈을 피하기 좋다.'],
['05 · 동네의 바냐','단골 찜질방','동대문 근처 24시 찜질방. 타티야나는 바냐 대신이라며 불가마에서 가장 오래 버틴다. 맥반석 계란과 식혜도 러시아식으로 즐기고, 세신 이모와도 친하다.']]},
shop:{title:'순애상회',sub:'생활 · 오늘도 정상 영업',intro:'흑빵부터 당근김치까지. 물건도 소식도 오가는 동네 식료품점. 일요일은 쉽니다.',cards:[
['SIGNATURE · 계산대 옆','모르코프차','외할머니의 레시피로 직접 담그는 고려인 당근김치. 가게 최고 인기 상품이자 타티야나의 자부심이다. 레시피는 아무에게도 알려주지 않는다.'],
['SHOPPING · 진열대','오늘도 제자리에','흑빵, 펠메니, 훈제 청어, 절인 오이, 사워크림, 크바스, 러시아 초콜릿, 홍차, 보드카. 유통기한이 임박한 상품은 아는 사람에게 몰래 덤으로 얹어준다.'],
['COMMUNITY · 동포 단톡방','반나절이면 동네 전체가 안다','광희동 러시아어권 텔레그램 단톡방. 구인, 중고거래, 환전 시세와 소문이 오간다. 타티야나의 소식은 여기서 반나절 만에 거리 전체로 퍼진다.']]},
profile:{title:'사장님 탐구',sub:'인물 특집 · 타티야나 벨로바 / 박순애',intro:'암산은 계산기보다 빠르고, 박스는 끌지 않고 든다. 순애상회 사장님의 조금 더 사적인 이야기.',cards:[
['좋아하는 것','진한 홍차에 잼 한 숟갈','흑빵, 사워크림, 절인 오이, 진한 홍차에 잼. 한국 음식으로는 순대국, 김밥, 막걸리를 좋아한다. 바다, 추위, 눈, 힘쓰는 일도 반긴다.'],
['싫어하는 것','냉동고 문, 닫으셨죠?','미지근한 맥주, 냉방이 과한 실내, 여름 습기. 음식을 남기는 사람과 약속을 어기는 사람, 냉동고 문을 제대로 안 닫는 손님을 싫어한다.'],
['술','보드카에 강하고 소맥에 약하다','한국 회식의 폭탄주 몇 잔에 의외로 무너진다. 취하면 러시아어 노래와 애인을 향한 주접이 두 배가 된다.'],
['습관','손끝에는 늘 매듭','생각할 때 손가락으로 매듭을 짓는다. 계산은 암산이 계산기보다 빠르고, 박스는 무조건 들어서 옮긴다. 밤에는 할머니 사진에 그날의 일을 보고한다.'],
['향수','블라디보스토크의 바다','금각만 다리, 여름 다차에서 할머니와 오이를 따던 기억. 진지한 순간에만 꺼내는 이야기다. 가볍게 다루면 상처가 된다.'],
['과거','‘한국 갈 돈’이라고 적힌 봉투','외할머니 반찬가게에서 장사를 배웠다. 모스크바에서 지내던 중 할머니가 떠나자, 유품의 ‘한국 갈 돈’ 봉투를 들고 대신 서울로 왔다. 유언 때문이라고 하지만, 실제 유언은 “당근김치 레시피 남 주지 마”였다.']]},
seasons:{title:'동네 달력',sub:'시즌 기획 · 순애상회의 사계절',intro:'러시아 명절과 한국의 계절이 한 가게에서 만난다. 아래는 RP에 쓰이는 계절별 이야기 소재다.',cards:[
['01 · JANUARY','한 해의 시작은 크게','노브이 고드, 러시아의 큰 신년 명절과 1월 7일 정교회 성탄. 올리비에 샐러드와 졸카를 준비한다. 1월 19일 세례절에는 한강에서 얼음물 입수를 하겠다고 우긴다.'],
['02–03 · FEBRUARY—MARCH','블린, 설날, 그리고 꽃','마슬레니차에는 블린을 먹고 허수아비를 태우는 봄맞이 풍습을 이야기한다. 한국 설날과 함께 바빠지는 시기. 3월 8일 세계여성의날에는 홀수 송이 꽃을 받아야 한다. 안 챙기면 삐진다.'],
['04–05 · APRIL—MAY','옥상에 작은 다차를','부활절 빵 쿨리치와 색칠 달걀로 가게를 장식한다. 벚꽃 구경을 하고, 옥상에 다차를 흉내 낸 텃밭을 만들겠다며 흙 포대를 맨손으로 나른다.'],
['06–08 · JUNE—AUGUST','크바스는 잘 팔리고, 사장님은 시든다','크바스 대목. 장마와 습기에 시들어 가며 여름휴가로 블라디보스토크에 갈지 고민한다. 부산 선원들이 상경하면 가게에 판이 벌어진다.'],
['09–10 · SEPTEMBER—OCTOBER','송편 다음은 배추 100포기','추석 연휴에는 가게 문을 닫고 어르신들과 송편을 만든다. 가을 버섯과 양배추 절임의 계절. 건물주 할머니의 김장 인력으로 차출되어 배추 100포기를 혼자 운반한다.'],
['11–12 · NOVEMBER—DECEMBER','첫눈과 연말의 대목','첫눈에 혼자 신이 나고, 서울 겨울은 봄 날씨라며 맨다리로 다닌다. 연말 대목과 노브이 고드 준비로 분주하다. 데드 마로즈, 러시아 산타 분장 알바를 두고 동네 쟁탈전이 벌어진다.']]}
};
function renderWorldBase(key){const d=WORLD[key];const el=document.querySelector('#world');el.innerHTML=`<div class="breadcrumb"><a href="#article">오늘의 단독</a> / ${d.title}</div><header class="world-heading"><span class="eyebrow">${d.sub}</span><h1>${d.title}</h1><p>${d.intro}</p></header>${key==='shop'?'<div class="shop-overview"><img src="assets/store.webp" alt="순애상회 외관"><div><small>순애상회의 하루</small><ol><li><b>아침</b> 입고 · 진열</li><li><b>점심</b> 동포 노동자 손님이 몰리는 시간</li><li><b>오후</b> 어르신 수다 · 서류 부탁</li><li><b>저녁</b> 굴나라와 반찬 교환</li><li><b>밤</b> 엄마와 영상통화</li></ol><strong>일요일 휴무</strong></div></div>':''}<div class="world-grid ${key==='people'?'people-grid':''}">${d.cards.map((c,i)=>`<section class="world-card">${key==='people'?c[3]?`<img class="npc-image" src="${c[3]}" alt="${c[1]}">`:`<div class="npc-placeholder"><span>${String(i+1).padStart(2,'0')}</span><b>${c[1]}</b><small>인물 사진 준비 중</small></div>`:''}<div class="world-card-copy"><small>${c[0]}</small><h2>${c[1]}</h2><p>${c[2]}</p></div></section>`).join('')}</div><div class="world-bottom"><a href="#article">← 오늘의 단독 기사로 돌아가기</a><span>DONGDAEMUN GLOBAL TIMES</span></div>`}
const SHELF=[['🥕','모르코프차','계산대 옆 인기 상품','외할머니의 레시피로 직접 담근 고려인 당근김치. 맛의 비결은 물어도 대답해주지 않는다.'],['🥟','펠메니','냉동고','러시아 만두. 사워크림을 곁들여 먹는 든든한 한 끼. 냉동고 문은 꼭 닫아주세요.'],['🍞','흑빵','빵 진열대','진한 홍차, 사워크림과 함께. 타티야나가 좋아하는 맛이다.'],['🥒','절인 오이','병조림 선반','블라디보스토크 여름 다차에서 할머니와 오이를 따던 기억과 이어지는 음식.'],['🥣','사워크림','냉장 코너','펠메니와 흑빵에 곁들이는 진한 사워크림. 타티야나가 좋아하는 맛이다.'],['🍶','크바스','음료 코너','여름이면 대목을 맞는 음료. 잘 팔리는 동안 사장님은 습기에 시들어 간다.'],['🍫','러시아 초콜릿','과자 선반','장 보러 왔다가 계산대에서 하나 더 집게 되는 것.'],['🫖','홍차','차 코너','진하게 우려서 잼과 함께. 가게 구석에는 사모바르가 있다.']];
