root.querySelector('.shop-overview').remove();const box=document.createElement('div');box.className='shop-play';box.innerHTML='<div class="shop-clock"><div class="shop-window"><img src="assets/store.webp" alt="순애상회"><span class="time-badge">09:00 · 입고 중</span></div><div class="clock-copy"><small>OPEN THE DAY · 시간을 눌러보세요</small><h2>순애상회의 하루</h2><div class="time-switch" role="group" aria-label="시간대 선택"></div><p class="day-story" aria-live="polite"></p><span class="closed-note">일요일은 쉽니다.</span></div></div><div class="shelf-head"><div><small>SHOP THE STORY</small><h2>순애상회 진열대</h2></div><span>상품을 눌러 살펴보세요 ↓</span></div><div class="product-shelf"></div><div class="product-note" aria-live="polite"></div>';heading.after(box);
const hours=[['아침','09:00 · 입고 중','문에 달린 종보다 박스 내려놓는 소리가 먼저 난다. 입고 상품을 확인하고 진열대를 채우는 시간.'],['점심','12:00 · 영업 중','동포 노동자 손님이 몰린다. 계산대가 가장 바쁜 시간. 타티야나의 암산은 계산기보다 빠르다.'],['오후','15:00 · 동네 사랑방','난로 옆에서는 어르신들의 수다가 이어진다. 아이게림은 행정서류를 들고 찾아온다.'],['저녁','19:00 · 반찬 교환','낮에는 손님을 두고 투닥이던 굴나라와 남은 음식을 나눈다. 가게의 하루도 천천히 저문다.'],['밤','22:00 · 본가 연결 중','블라디보스토크에서 엄마의 영상통화가 걸려 온다. 밥, 옷차림, 결혼 이야기. 잠들기 전에는 할머니 사진에 오늘을 보고한다.']];
const sw=box.querySelector('.time-switch');function time(i){box.querySelector('.time-badge').textContent=hours[i][1];box.querySelector('.day-story').textContent=hours[i][2];box.querySelector('.shop-window').dataset.time=i;box.querySelector('.shop-window img').src='assets/'+DAY_IMAGES[i]+'.webp';box.querySelector('.shop-window img').alt=['순애상회 외관','영업 중인 순애상회','난로와 사모바르가 있는 가게 구석','사모바르 곁의 티테이블','밤의 순애상회'][i];[...sw.children].forEach((b,j)=>{b.classList.toggle('active',i===j);b.setAttribute('aria-pressed',i===j)})}hours.forEach((h,i)=>{const b=document.createElement('button');b.textContent=h[0];b.onclick=()=>time(i);sw.append(b)});time(0);
const shelf=box.querySelector('.product-shelf');function product(i){const d=SHELF[i];box.querySelector('.product-note').innerHTML=`<img src="assets/${PRODUCT_IMAGES[i]}.webp" alt="${d[1]}" class="selected-product-image"><div><small>${d[2]}</small><h3>${d[1]}</h3><p>${d[3]}</p></div>`;[...shelf.children].forEach((b,j)=>{b.classList.toggle('selected',i===j);b.setAttribute('aria-pressed',i===j)})}SHELF.forEach((d,i)=>{const b=document.createElement('button');b.innerHTML=`<img src="assets/${PRODUCT_IMAGES[i]}.webp" alt="${d[1]}" loading="lazy"><b>${d[1]}</b><small>자세히 보기 ＋</small>`;b.onclick=()=>product(i);shelf.append(b)});product(0);
