const hero=document.createElement('div');hero.className='profile-feature';hero.innerHTML='<figure class="profile-portrait"><img src="assets/tea-boxes.webp" alt="상자를 든 채 홍차를 마시는 타티야나"><figcaption><b>현장 인터뷰</b> 상자는 한 손에. 홍차는 다른 손에.</figcaption></figure><div><small>DGT PEOPLE · 순애상회에서 만났습니다</small><h2>타티야나 벨로바.<br><em>동네에선 박순애.</em></h2><p>29세 · 블라디보스토크 출신<br>순애상회 사장 · 당근김치 레시피 보유자</p><a href="https://youtu.be/KYllq4WVf0k?si=p8aK3KyhXco90k_3" target="_blank" rel="noopener">▶ 내 보물단지 MV</a></div>';heading.after(hero);[...grid.children].forEach((card,i)=>{const copy=card.querySelector('.world-card-copy'),p=copy.querySelector('p');p.hidden=true;const b=document.createElement('button');b.className='dossier-toggle';b.textContent='취재 수첩 펼치기 ＋';b.setAttribute('aria-expanded','false');b.onclick=()=>{p.hidden=!p.hidden;b.textContent=p.hidden?'취재 수첩 펼치기 ＋':'취재 수첩 접기 −';b.setAttribute('aria-expanded',!p.hidden);card.classList.toggle('opened',!p.hidden)};copy.append(b);card.classList.add('dossier');card.dataset.number=String(i+1).padStart(2,'0')});
